import manifest from "./manifest.generated.json";

/**
 * Sound playback for the smash view (Web Audio).
 *
 * Files live in public/sounds/<object>/<tool>/<event>[_N].<ext>, e.g.
 * public/sounds/can/press/crunch_2.mp3. A file in _common/<tool>/ is used
 * when the object has none for that event. Missing sounds are silent, so
 * the app works before every file exists. The file list is generated by
 * scripts/gen-sounds.mjs on `npm run dev` / `npm run build`.
 */

export type SoundObject = "laptop" | "book" | "can";
export const SOUND_OBJECTS: { id: SoundObject; label: string }[] = [
  { id: "laptop", label: "노트북" },
  { id: "book", label: "책" },
  { id: "can", label: "캔 음료" },
];

export interface PlayOptions {
  object?: SoundObject;
  tool: string;
  /** 0-1. */
  volume?: number;
}

const FILE = /^(.+)\/([^/]+)\/([a-z0-9-]+?)(?:_\d+)?\.(mp3|ogg|wav|m4a|webm)$/i;

/** "<object>/<tool>/<event>" → variant files. */
const index = new Map<string, string[]>();
for (const path of (manifest as { files: string[] }).files) {
  const m = FILE.exec(path);
  if (!m) continue;
  const key = `${m[1]}/${m[2]}/${m[3]}`.toLowerCase();
  index.set(key, [...(index.get(key) ?? []), path]);
}

class SoundEngine {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private buffers = new Map<string, Promise<AudioBuffer | null>>();
  private loops = new Map<string, { source: AudioScheduledSourceNode; gain: GainNode }>();
  private rate = 1;
  muted = false;
  /** Sound sync mode: a beep (or hum, for loops) wherever a file is missing. */
  placeholder = false;

  private context() {
    if (!this.ctx) {
      this.ctx = new AudioContext();
      this.master = this.ctx.createGain();
      this.master.connect(this.ctx.destination);
    }
    return this.ctx;
  }

  /** Call from a tap/click handler: mobile browsers only allow audio after a gesture. */
  unlock() {
    const ctx = this.context();
    if (ctx.state === "suspended") void ctx.resume();
  }

  setMuted(muted: boolean) {
    this.muted = muted;
    if (this.master) this.master.gain.value = muted ? 0 : 1;
  }

  /** Slow motion: everything plays slower and lower. */
  setTimeScale(scale: number) {
    this.rate = scale;
    for (const { source } of this.loops.values()) {
      if (source instanceof AudioBufferSourceNode) source.playbackRate.value = scale;
    }
  }

  /** Files for an event: the object's own, else the shared ones. */
  files(event: string, o: PlayOptions) {
    const own = o.object ? index.get(`${o.object}/${o.tool}/${event}`) : undefined;
    return own ?? index.get(`_common/${o.tool}/${event}`) ?? [];
  }

  private load(path: string) {
    let p = this.buffers.get(path);
    if (!p) {
      p = fetch(`/sounds/${path}`)
        .then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(`${r.status} ${path}`))))
        .then((data) => this.context().decodeAudioData(data))
        .catch((e) => {
          console.warn("[sound]", e);
          return null;
        });
      this.buffers.set(path, p);
    }
    return p;
  }

  /** Fetch and decode everything an object can use, so the first hit isn't late. */
  preload(object?: SoundObject) {
    for (const [key, paths] of index) {
      if (key.startsWith("_common/") || (object && key.startsWith(`${object}/`))) paths.forEach((p) => this.load(p));
    }
  }

  /** One-shot. Picks a random variant and nudges pitch so repeats don't sound copied. */
  async play(event: string, o: PlayOptions) {
    const paths = this.files(event, o);
    if (!paths.length) return this.beep(o.tool, event, o.volume);
    const buffer = await this.load(paths[Math.floor(Math.random() * paths.length)]);
    const ctx = this.ctx;
    if (!buffer || !ctx || !this.master) return;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = this.rate * (0.95 + Math.random() * 0.1);
    const gain = ctx.createGain();
    gain.gain.value = o.volume ?? 1;
    source.connect(gain).connect(this.master);
    source.start();
  }

  /** Start a looping sound under `id` (no-op if already running). */
  async loop(id: string, event: string, o: PlayOptions) {
    if (this.loops.has(id)) return;
    const paths = this.files(event, o);
    if (!paths.length) return this.hum(id, o.tool, event, o.volume);
    const buffer = await this.load(paths[0]);
    const ctx = this.ctx;
    if (!buffer || !ctx || !this.master || this.loops.has(id)) return;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    source.playbackRate.value = this.rate;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(o.volume ?? 1, ctx.currentTime + 0.08);
    source.connect(gain).connect(this.master);
    source.start();
    this.loops.set(id, { source, gain });
  }

  /** Change a running loop's volume (e.g. press creak getting louder). */
  loopVolume(id: string, volume: number) {
    const l = this.loops.get(id);
    if (l && this.ctx) l.gain.gain.setTargetAtTime(volume, this.ctx.currentTime, 0.05);
  }

  stop(id: string) {
    const l = this.loops.get(id);
    if (!l || !this.ctx) return;
    this.loops.delete(id);
    const t = this.ctx.currentTime;
    l.gain.gain.cancelScheduledValues(t);
    l.gain.gain.setValueAtTime(l.gain.gain.value, t);
    l.gain.gain.linearRampToValueAtTime(0, t + 0.12);
    l.source.stop(t + 0.13);
  }

  /** Placeholder one-shot: a short blip, its pitch fixed per event so they can be told apart. */
  private beep(tool: string, event: string, volume = 1) {
    const ctx = this.ctx;
    if (!this.placeholder || !ctx || !this.master) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = "triangle";
    osc.frequency.value = pitch(tool, event) * this.rate;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.4 * Math.max(0.3, volume), t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    osc.connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.13);
  }

  /** Placeholder loop: a quiet buzz under `id` until stop(id). */
  private hum(id: string, tool: string, event: string, volume = 1) {
    const ctx = this.ctx;
    if (!this.placeholder || !ctx || !this.master) return;
    const osc = ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.value = pitch(tool, event) / 2;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0.08 * volume, ctx.currentTime + 0.08);
    osc.connect(gain).connect(this.master);
    osc.start();
    this.loops.set(id, { source: osc, gain });
  }

  stopAll() {
    for (const id of [...this.loops.keys()]) this.stop(id);
  }
}

export const sound = new SoundEngine();

/** 300-1200 Hz, the same for the same event every time. */
function pitch(tool: string, event: string) {
  let h = 0;
  for (const c of `${tool}/${event}`) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  return 300 * 2 ** ((h % 1000) / 500);
}

/**
 * Which demo object's sound set to use, from Claude's labels. "notebook" in
 * English is ambiguous (paper vs laptop), so material decides that case.
 */
export function soundObjectFor(v?: { label_en: string; label_ko: string; material: string }): SoundObject | undefined {
  if (!v) return undefined;
  const label = `${v.label_en} ${v.label_ko}`.toLowerCase();
  if (/laptop|macbook|노트북|컴퓨터/.test(label) || v.material === "electronics") return "laptop";
  if (/\bcan\b|캔|soda|cola|beer|beverage|음료/.test(label) || v.material === "metal") return "can";
  if (/book|책|novel|magazine|공책/.test(label) || v.material === "paper") return "book";
  return undefined;
}
